// The embedded player: web/dist files baked into the binary at compile
// time (web_server serves these when no [server].web_root override is
// set). The table is GENERATED by CMake at configure time from web/dist,
// which ./build.sh fetches from the latest websrt-wasm-cpp release
// artifact - this repo never
// builds the player. A configure without web/dist is a fatal error, so a
// built binary always carries the player.

#ifndef WEBSRT_GATEWAY_EMBEDDED_PLAYER_H
#define WEBSRT_GATEWAY_EMBEDDED_PLAYER_H

#include <string_view>
#include <vector>

namespace quicsrt::gateway
{

/// One embedded file: web-root-relative POSIX path ("/index.html") and
/// its bytes. Both point into static storage for the process lifetime.
struct EmbeddedAsset
{
    std::string_view path;
    std::string_view bytes;
};

/// Every embedded player file, path-sorted ascending. Never empty.
const std::vector<EmbeddedAsset>& EmbeddedPlayerFiles();

} // namespace quicsrt::gateway

#endif // WEBSRT_GATEWAY_EMBEDDED_PLAYER_H
